import React, { useState, useEffect } from 'react';
import { Routes, Route, useLocation } from 'react-router-dom';
import Navigation from './components/Navigation';
import MainFeed from './components/MainFeed';
import Board from './components/Board';
import Timetable from './components/Timetable';
import Marketplace from './components/Marketplace';
import Map from './components/Map';
import MyPage from './components/MyPage';
import SeasonalTheme from './components/SeasonalTheme';
import JapaneseMascot from './components/JapaneseMascot';
import PushNotifications from './components/PushNotifications';
import './App.css';

function App() {
  const [currentTab, setCurrentTab] = useState('home');
  const [user, setUser] = useState({
    id: 1,
    name: '田中太郎',
    username: '@tanaka_taro',
    avatar: '👤',
    department: '工学部',
    year: 3,
    isAnonymous: false
  });
  const location = useLocation();

  useEffect(() => {
    const path = location.pathname;
    if (path === '/') setCurrentTab('home');
    else if (path === '/board') setCurrentTab('board');
    else if (path === '/timetable') setCurrentTab('timetable');
    else if (path === '/marketplace') setCurrentTab('marketplace');
    else if (path === '/map') setCurrentTab('map');
    else if (path === '/mypage') setCurrentTab('mypage');
  }, [location]);

  return (
    <SeasonalTheme>
      <div className="app">
        <div className="app-container">
          <main className="main-content">
            <Routes>
              <Route path="/" element={<MainFeed user={user} setUser={setUser} />} />
              <Route path="/board" element={<Board user={user} />} />
              <Route path="/timetable" element={<Timetable user={user} />} />
              <Route path="/marketplace" element={<Marketplace user={user} />} />
              <Route path="/map" element={<Map user={user} />} />
              <Route path="/mypage" element={<MyPage user={user} setUser={setUser} />} />
            </Routes>
          </main>
          <Navigation currentTab={currentTab} />
          <JapaneseMascot mood="happy" size="medium" position="floating" />
          <PushNotifications />
        </div>
      </div>
    </SeasonalTheme>
  );
}

export default App;
